import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"水地比","description":"周易折中 - 水地比","frontmatter":{"title":"水地比","description":"周易折中 - 水地比"},"headers":[],"relativePath":"zh/classics/zhezhong/014.md","filePath":"zh/classics/zhezhong/014.md"}'),h={name:"zh/classics/zhezhong/014.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="水地比" tabindex="-1">水地比 <a class="header-anchor" href="#水地比" aria-label="Permalink to “水地比”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>比序卦：众必有所比，故受之以比。比亲辅也，人之类必相亲辅然后能安。故既有众，则必有所比。比所以次师也，为卦上坎下坤。以二体言之，水在地上，物之相切比无闲，莫如水之在地上，故为比也。又众爻皆阴，独五以阳刚居君位，众所亲附，而上亦亲下，故为比也。</p><p>比：吉。原筮，元永贞，无咎。不宁方来，后夫凶。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>比，亲辅也。九五以阳刚居上之中而得其正，上下五阴比而从之。以一人而橅万邦，以四海而仰一人之象。故筮者得之，则当为人所亲辅。然必再筮以自审，有元善长、永正固之德，然后可以当众之归而无咎。其未比而有所不安者，亦将皆来归之。若又迟而后至，则此交已固，彼来已晚，而得凶矣。若欲比人，则亦以是而反观之耳。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>比吉，道也。人相亲比，自为吉道。故杂卦云：“比乐师忧。”人相亲比，必有其道。苟非其道，则有悔咎。故必推原占决，其可比者而比之。筮谓占决卜度，非谓以蓍龟也。所比得元永贞，则无咎。元谓有君长之道，永谓可以常久，贞谓得正道。上之比下，必有此三者。下之从上，必求此三者，则无咎也。人之不能自保其安宁，方且来求亲比。得所比，则能保其安。当其不宁之时，固宜汲汲以求比。若独立自恃，求比之志不速，而后则虽夫亦凶矣。夫犹凶，况柔弱者乎？夫，刚立之称。传曰：“子南夫也。”又曰：“是谓我非夫。”凡生天地之间者，未有不相亲比而能自存者也。虽刚强之至，未有能独立者也。比之道，由两志相求。两志不相求，则睽矣。君怀抚其下，下亲辅于上。亲戚朋友乡党皆然，故当上下合志以相从。苟无相求之意，则离而凶矣。大抵人情相求则合，相持则睽。相持相待，莫先也。人之相亲固有道，然而欲比之志不可缓也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰：一阳之卦，得位者师、比而已。得君位者为比，得臣位者为师。</p></li><li><p>冯氏椅曰：萃与比下体坤顺，同上体水泽不相逺。惟九四一爻有分权之象，故元永贞言于五。比下无分权者，故元永贞言于卦。义各有在也。</p></li><li><p>胡氏一桂曰：六十四卦，惟䝉、比以筮言。䝉贵初，而比贵原者，盖发䝉之道，当视其初筮之专诚；显比之道，当致其原筮而谨审。所以不同也。</p></li><li><p>胡氏炳文曰：原筮，本义读如原蚕、原庙、原田之原，义皆训再。曰吉，曰无咎，曰凶，皆占辞。吉，上下相比之占，统言也。无咎，所比者之占；凶，比人者之占，分言也。䝉、比卦辞特发两筮字，以示占者之通例。筮得䝉卦辞，䝉求亨者与亨䝉者皆可用；筮得此卦辞，为人所比与求比者皆可用。顾其所处所存者何如耳。䝉之筮问之人者，不一则不专；比之筮问其在我者，不再则不审。不寜方来，指下四阴而言。来者自来，后者自后，吾惟问我之可比不可比，彼之来比不来比，吾不问也。此固王者大公之道，而为九五之显比者也。</p></li></ul><p>象曰：地上有水，比。先王以建万国，亲诸侯</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>地上有水，水比于地，不容有间。建国亲侯，亦先王所以比于天下而无间者也。彖意人来比我，此取我往比人。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>夫物相亲比而无间者，莫如水在地上，所以为比也。先王观比之象，以建万国，亲诸侯。建立万国，所以比民也；亲抚诸侯，所以比天下也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张氏浚曰：水行地上，小大相比，率以归东。先王法之，建万国以下比其民，亲诸侯以上比其君，若身使臂，臂使指，小大相维，顺以听命，制得其道也。</p></li><li><p>朱子语类云：伊川言建万国以比民，民不可尽得而比，故建诸侯使比民，而天子所亲者诸侯而已，这便是比天下之道。</p></li><li><p>冯氏当可曰：地上之水，异源同流，畎浍相比以比于川，九川相比以比于海，如万国诸侯大小相比，而方伯连帅率之以比于天子也。</p></li><li><p>胡氏炳文曰：师之容民畜众，井田法也，可以使民自相合而无间；比之建国亲侯，封建法也，可使君与民相合而无间。</p></li></ul><p>彖曰：比，吉也。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>此三字疑衍文</p><p>比，辅也；下顺从也。</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>此以卦体释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>比吉也。比者，吉之道也。物相亲比乃吉道也。比辅也，释比之义。比者相亲附也，下顺从也，解卦所以为比也。五以阳居尊位，群下顺从以亲辅之，之所以为比也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：“比吉也者”，言相亲比而得吉也。“比辅也者”，释比所以得吉。“下顺从者”，谓众阴顺从九五也。</p></li><li><p>朱子语类云：“比吉也”也字羡，当云“比吉”。“比辅也，下顺从也”，比辅也解“比”字，下顺从也解“吉”字。</p></li><li><p>杨氏启新曰：“下顺从”以卦体言，实则兼上下。众阴不曰“上下”而曰“下”者，以九五为主也。至“不宁方来”则曰“上下应”，前是尊上之辞，后是举众之辞。</p></li></ul><p>原筮元永贞，无咎。以刚中也，不宁方来，上下应也。后夫凶，其道穷也。</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>亦以卦体释卦辞。刚中谓五，上下谓五阴。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>推原筮决相比之道，得元永贞而后可以无咎。所谓元永贞，如五是也。以阳刚居中正，尽比道之善者也。以阳刚当尊位为君德元也，居中得正，能永而贞也。卦辞本泛言比道，彖言元永贞者，九五以刚处中正是也。人之生不能保其安宁，方且来求附比。民不能自保，故戴君以求宁。君不能独立，故保民以为安。不宁而来比者，上下相应也。以圣人之公言之，固至诚求天下之比以安民也；以后王之私言之，不求下民之附则危亡至矣。故上下之志必相应也。在卦言之，上下群阴比于五，五比其众，乃上下应也。众必相比而后能遂其生，天地之间，未有不相亲比而能遂者也。若相从之志不疾，后则不能成比，虽夫亦凶矣。无所亲比，困屈以致凶穷之道也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：凡应字多谓刚柔两爻相应，此则谓上下。五阴应乎五之刚，又一例也。师、比皆一阳五阴，师之应谓五应二，将之任专也；比之应则谓上下应五，君之分严也。</li></ul><p>初六：有孚比之，无咎；有孚盈缶，终来有它吉。</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>有孚比之，无咎；若其充实，则又有它吉也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>初六，比之始也。相比之道，以诚信为本。中心不信而亲人，人谁与之？故比之始，必有孚诚，乃无咎也。孚，信之在中也。诚信充实于内，若物之盈满于缶中也。缶，质素之器。言若缶之盈实其中，外不加文餙，则终能来有它吉也。它，非此也，外也。若诚实充于内，物无不信，岂用餙外以求比乎？诚信中实，虽它外皆当感而来从。孚信，比之本也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郑氏汝谐曰：五为比之主，初最远而非其应，何以有吉义？盖几生于应物之先，而诚出于志之未变，故以信求比，何咎之有？盈，充也。缶，素器也。居下而位卑，扩吾之信以充之，虽逺而非其应，终必应而有它吉矣。有它吉者，非期于必得而得之也。</p></li><li><p>胡氏炳文曰：与人交，止于信。亲比之初，能有诚信，所以比之无咎。及其诚信充实，则非特无咎，又有它吉。初六不与五应，故曰有它。大过九四、中孚初九皆曰有它，彼则戒其有它向之心，此则许其有它至之吉也。</p></li></ul><p>象曰：比之初六，有孚比之，无咎。有孚盈缶，终来有它吉</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>言比之初六者，比之道在乎始也。始能有孚，则终致有它之吉。其始不诚，终焉得吉？上六之凶，由无首也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>蒋氏悌生曰：爻辞有孚，凡两更端及盈缶等语，象传皆略之，直举初六为言，可见比之要道在乎始。先此义与卦辞“后夫凶”之意相发明。</li></ul><p>六二：比之自内，贞吉。</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>柔顺中正，上应九五，自内比外而得其正，吉之道也。占者如是，则正而吉矣。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二与五为正应，皆得中正，以中正之道相比者也。二处于内，自内谓由已也。择才而用，虽在乎上，而以身许国，必由于己。已以得君，道合而进，乃得正而吉也。以中正之道应上之求，乃自内也，不自失也。汲汲以求比者，非君子自重之道，乃自失也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>梁氏寅曰：二与五为比，由内而比外者也。凡贞吉，有爻之本善者，有爻非贞而为之戒者。此曰贞吉，爻之本善也。言自内比外而得其正，是以吉也。</p></li><li><p>谷氏家杰曰：自内之所有者，以比之逹不变塞也。即此是正，故吉。</p></li></ul><p>象曰：比之自内，贞吉</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>得正则不自失矣。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>守己中正之道以待上之求，乃不自失也。易之为戒严密，二虽中正质柔体顺，故有贞吉自失之戒。戒之自守以待上之求，无乃渉后凶乎？曰：士之脩己乃求上之道，降志辱身非自重之道也，故伊尹、武侯救天下之心非不切，必待礼至然后出也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱氏震曰：六二柔也，恐其自失也。二处乎内，待上之求然后应之，比之自内者也，故曰不自失也。</li></ul><p>六三：比之匪人。</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>阴柔不中正，承乘应皆阴，所比皆非其人之象，其占大凶，不言可知。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>三不中正，而所比皆不中正。四阴柔而不中，二存应而比初，皆不中正，匪人也。比于匪人，其失可知，悔吝不假言也，故可伤。二之中正而谓之匪人，随时取义，各不同也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：四自外比二，为五应近不相得，远则无应，所与比者皆非已亲，故曰“比之匪人”。</p></li><li><p>朱子语类云：初应四为比得其人，二应五亦为比得其人，惟三乃应上，上为比之无首者，故为“比之匪人”也。</p></li><li><p>赵氏彦肃曰：初比于五，先也；二应也；四承也；六三无是三者之义，将不能比五矣。</p></li></ul><p>象曰：比之匪人，不亦伤乎</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>人之相比，求安吉也。乃比于匪人，必将反得悔吝，其亦可伤矣。深戒失所比也。</p><p>六四：外比之，贞吉。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>以柔居柔，外比九五，为得其正，吉之道也。占者如是，则正而吉矣。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四与初不相应，而五比之外，比于五乃得贞正而吉也。君臣相比，正也。相比相与，宜也。五刚阳中正，贤也，居尊位在上也。亲贤从上，比之正也，故为贞吉。以六居四，亦为得正之义。又阴柔不中之人，能比于刚明中正之贤，乃得正而吉也。又比贤从上，必以正道，则吉也。数说相须，其义始备。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>易氏祓曰：易以上卦为外，下卦为内。而二体亦各有内外，四与五同体而言外比者，亦所以比五也。</p></li><li><p>李氏过曰：二与四皆比于五，二应五在卦之内，故言“比之自内”；四承五在卦之外，故言“外比”。之外内虽异，而得其所比，其义一也，故皆言贞吉。</p></li></ul><p>象曰：外比于贤，以从上也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>外比谓从五也。五刚明中正之贤，又居君位，四比之，是比贤且从上，所以吉也。</p><p>九五：显比，王用三驱，失前禽，邑人不诫，吉。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>一阳居尊，刚健中正，卦之群阴皆来比已，显其比而无私，如天子不合围，开一面之网，来者不拒，去者不追，故为用三驱失前禽而邑人不诫之象。盖虽私属亦喻上意，不相警备以求必得也。凡此皆吉之道，占者如是则吉也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>五居君位，处中得正，尽比道之善者也。人君比天下之道，当显明其比道而已。如诚意以待物，恕己以及人，发政施仁，使天下蒙其惠泽，是人君亲比天下之道也。如是，天下孰不亲比于上？若乃暴其小仁，违道干誉，欲以求下之比，其道亦狭矣，其能得天下之比乎？故圣人以九五尽比道之正，取三驱为喻曰：王用三驱，失前禽，邑人不诫吉。先王以四时之畋不可废也，故推其仁心为三驱之礼，乃礼所谓天子不合围也。成汤祝网是其义也。天子之畋，围合其三面，前开一路，使之可去，不忍尽物，好生之仁也。只取其不用命者，不出而反入者也。禽兽前去者皆免矣，故曰失前禽也。王者显明其比道，天下自然来比，来者抚之，固不煦煦然求比于物，若田之三驱，禽之去者从而不追，来者则取之也。此王道之大，所以其民皡皡而莫知为之者也。邑人不诫，吉言其至公不私，无远迩亲踈之别也。邑者，居邑，易中所言邑皆同。王者所都，诸侯国中也。诫，期约也。待物之一，不期诫于居邑，如是则吉也。圣人以大公无私治天下，于显比见之矣。非惟人君比天下之道如此，大率人之相比莫不然。以臣于君言之，竭其忠诚，致其才力，乃显其比君之道也。用之与否在君而已，不可阿谀逢迎求其比已也。在朋友亦然，修身诚意以待之，亲已与否在人而已，不可巧言令色曲从苟合以求人之比己也。于乡党亲戚于众人莫不皆然，三驱失前禽之义也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类 问：伊川解“显比，王用三驱，失前禽”所谓“来者抚之，去者不追”与“失前禽而杀不去者”所譬颇不相类，如何？ 曰：田猎之礼，置旃以为门，刈草以为长围。田猎者自门驱而入，禽兽向我而出者皆免，惟被驱而入者皆获。故以前禽比去者不追，获者比来则取之。大意如此，无缘得一一相似。伊川解此句不须疑，但“邑人不诫吉”一句似可疑，恐易之文义不如此耳。 又云：邑人不诫，如有闻无声，言其自不消相告诫。又如归市者不止，耕者不变相似。</p></li><li><p>问：伊川解“显比，王用三驱，失前禽”所谓“来者抚之，去者不追”与“失前禽而杀不去者”所譬颇不相类，如何？ 曰：田猎之礼，置旃以为门，刈草以为长围。田猎者自门驱而入，禽兽向我而出者皆免，惟被驱而入者皆获。故以前禽比去者不追，获者比来则取之。大意如此，无缘得一一相似。伊川解此句不须疑，但“邑人不诫吉”一句似可疑，恐易之文义不如此耳。</p></li><li><p>又云：邑人不诫，如有闻无声，言其自不消相告诫。又如归市者不止，耕者不变相似。</p></li><li><p>胡氏炳文曰 ：诸阴爻皆言比，阴比阳也。五言显比，阳为阴所比也。师比之五皆取田象，师之田有禽，害物之禽也；比之失前禽，背已之禽也。在师则执之，王者之义也；在比能失之，王者之仁也。</p></li><li><p>梁氏寅曰 ：九五阳刚中正，为比之主。阳刚则明而不暗，中正则公而不私，此其所以为显比也。以象言之，如田狩而用三驱，失前禽，来者不拒，去者不追，此上之比下也，固显比也；比下既得其道，则虽私属亦喻上意而不待告诫，此下之比上也，亦显比也。上下之相比，同一显明之道，又安有不吉乎？</p></li><li><p>林氏希元曰 ：显与隐对，光明正大而无隐伏回曲暗昧褊窄者显也，隐伏回曲暗昧褊窄而不光明正大者隐也。王者以父母天下为职，生养教诲，但知吾分所当为，尽其道而为之，至于民之感恩与否则听其在彼，初不屑屑焉。暴其私恩小惠，违道干誉，以求百姓之我亲，此其施为举措何等光明正大，而岂有隐伏回曲暗昧褊窄之病？故谓之显比。譬如王者解一面之网，用三驱之田，禽兽向我而入者取之，背我而前去者则失之，初不求于必得。至于私属亦喻上意，不相警备以求必得焉。夫王用三驱，失前禽者，王道之得；邑人不诫者，王化之行。凡此皆吉之道也。王者能如九五之显比，则亦王道得而王化行矣。</p></li><li><p>陆氏振奇曰 ：三驱失禽，置失得于勿恤者，状荡平之王心；邑人不诫，泯知识于大顺者，状熙皥之王化。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>本义解“邑人不诫”谓不相警备以求必得，似以为求所失之前禽也。然语类只作“冇闻无声”之意，尤为精切。盖言王者田猎而近郊之处略不惊扰耳。本义系朱子未脩改之书，故其后来讲论每有不同者皆此类也。大抵爻意是以田猎喻王者皥皥之气象，前禽失而不追，邑人居而不诫。远去者若不知有王者之亲，乃所以为亲之至也；近附者若不知有王者之尊，乃所以为尊之至也。显比之世，凡有血气莫不尊亲，而所谓大顺大化不见其迹者又如此。</p><p>象曰：显比之吉，位正中也。舍逆取顺，失前禽也。邑人不诫，上使中也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>由上之德使不偏也。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>显比所以吉者，以其所居之位得正中也。处正中之地，乃由正中之道。比以不偏为善，故云正中。凡言正中者，其处正得中也。比与随是也。言中正者，得中与正也，讼与需是也。礼取不用命者，乃是舍顺取逆也。顺命而去者皆免矣。比以向背而言，谓去者为逆，来者为顺也。故所失者前去之禽也。言来者抚之，去者不追也。不期诫于亲近，上之使下中平不偏，远近如一也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>丘氏富国曰：舍逆谓舍上一阴，阴以乘阳为逆也；取顺谓取下四阴，阴以承阳为顺也。失上一阴，故曰失前禽。</p></li><li><p>胡氏炳文曰：师之使不当，谁使之？五也。比之使中，谁使之？亦五也。</p></li></ul><p>上六：比之无首，凶。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>阴柔居上，无以比下，凶之道也，故为无首之象，而其占则凶也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>六居上，比之终也。首，谓始也。凡比之道，其始善，则其终善矣。有其始而无其终者或有矣，未有无其始而有终者也。故比之无首，至终则凶也。此据比终而言，然上六阴柔不中，处险之极，固非克终者也。始比不以道，隙于终者，天下多矣。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：无首，后也。处卦之终，是后夫也。为时所弃，宜其凶也。</p></li><li><p>王氏申子曰：五以一阳居尊，四阴比之于下，故彖传曰“下顺从也”。而上六孤立于外而不从，岂非后夫之象？</p></li></ul><p>象曰：比之无首，无所终也</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>以上下之象言之，则为无首；以终始之象言之，则为无终。无首则无终矣。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>比既无首，何所终乎？相比有首，犹或终违。始不以道终，复何保？故曰无所终也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰：由初而比之，其比也诚。比不于其初及终而始求比，不忠不信，人所不与，凶之道也。首，初也。有始则有终，无始何以能终？故曰无所终也。</p></li><li><p>蒋氏悌生曰：即卦辞“后夫凶”之义。</p></li></ul>',110)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
